public AuthResponse registerAppUser(RegisterRequest req) {
    if (userRepository.existsByUsername(req.getUsername())) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, "用户名已存在");
    }
    UserEntity u = new UserEntity();
    u.setUsername(req.getUsername());
    u.setPasswordHash(passwordEncoder.encode(req.getPassword()));
    u.setRole(UserRole.APP_USER);
    u.setProfileComplete(false);
    userRepository.save(u);
    String token = jwtService.generateToken(u.getId(), u.getUsername(), UserRole.APP_USER);
    return new AuthResponse(token, UserMapper.toDto(u));
}

@PostMapping("/example")
public AiExampleResponse example(Authentication auth, @RequestBody AiExampleRequest body) {
    String text = aiService.generateExample((Long) auth.getPrincipal(), body.getWord(),
            body.getPhonetic(), body.getTranslation());
    return new AiExampleResponse(text);
}

public static int weightAfterSpellingResult(int currentWeight, boolean correct) {
    int next = correct ? currentWeight + 1 : currentWeight - 1;
    return clampWeight(next);
}

public static long nextReviewTime(long now, int newWeight, boolean correct) {
    if (!correct && newWeight <= HARD_LEARNED_WEIGHT) {
        return now + WRONG_REVIEW_DELAY_MS;
    }
    if (newWeight >= MASTERED_WEIGHT) {
        return now + MASTERED_DECAY_DELAY_MS;
    }
    return now + LEARNED_REVIEW_DELAY_MS;
}
